    blanks = "def f():\n    x = 0\n" + "".join(f"    x += {i}\n\n" for i in range(40)) + "    return x\n"
    comments = (
        "def f():\n    x = 0\n"
        + "".join(f"    # c{i}\n    x += {i}\n" for i in range(40))
